/* 派生字段：id / year */
SHOWS.forEach(s => { s.year = +s.date.slice(0, 4); s.id = s.date + '-' + s.city; });

/* 省级行政区场次聚合 */
function buildProvinceStats() {
  const map = {};
  SHOWS.forEach(s => {
    if (!map[s.province]) map[s.province] = { province: s.province, count: 0, cities: new Set(), years: new Set() };
    map[s.province].count++;
    map[s.province].cities.add(s.city);
    map[s.province].years.add(s.year);
  });
  return Object.values(map).filter(p => p.count > 0).map(p => ({
    province: p.province,
    count: p.count,
    cities: [...p.cities],
    years: [...p.years].sort()
  })).sort((a, b) => b.count - a.count);
}

const PROVINCE_STATS = buildProvinceStats();
